public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of visited n-tersections
    boolean[][] visited = new boolean[n][n];

    // Initialize a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]][start[1]] = true;
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Loop through all adjacent n-tersections
        for (int[] path : paths) {
            // If the adjacent n-tersection is not visited, mark it as visited and add it to the queue
            if (!visited[path[0]][path[1]]) {
                visited[path[0]][path[1]] = true;
                queue.add(path);
            }
        }
    }

    // If the queue is empty and the ending n-tersection was not reached, return "cannot be travelled"
    return "cannot be travelled";
}

